t.guides["forever/alliance/30-40/04-stranglethorn-vale"] = (function() return {
		["Back south past Nesingwary: Panthers and Stranglethorn Raptors run in the clearings west of the camp toward the coast; the elder tigers hold the hills south-west."] = "De vuelta al sur pasando a Nesingwary: las panteras y los raptores de Tuercespina corren por los claros al oeste del campamento hacia la costa; los tigres mayores ocupan las colinas del suroeste.",
		["Bloodscalp trolls"] = "Trols Sangrapellejo",
		["Both roam the grass around the camp and along the road north."] = "Ambos deambulan por la hierba alrededor del campamento y a lo largo del camino al norte.",
		["Druid training"] = "Entrenamiento de druida",
		["Follow the west coast north; the haunted island lies off the shore west of Nesingwary's camp. Just reach it."] = "Sigue la costa oeste al norte; la isla embrujada está frente a la costa, al oeste del campamento de Nesingwary. Solo llega hasta ella.",
		["For Archmage Ansirem in {zone:1416}"] = "Para el archimago Ansirem en {zone:1416}",
		["Gluggle, a rare murloc on the coast west of camp, drops the {item:4614}: take it if you meet him"] = "Gluggle, un múrloc raro en la costa al oeste del campamento, suelta {item:4614}: tómalo si te lo encuentras",
		["Headshrinkers stand deeper in the compound; the Commandos lurk stealthed around it and in the cave. Pick up Green Hills pages as they drop."] = "Los reductores de cabezas están más adentro de la base; los comandos acechan en sigilo a su alrededor y en la cueva. Recoge las páginas de Las verdes colinas cuando caigan.",
		["Herod's records lie in a hut on the compound's west side; his strongbox sits farther east, by the cave mouth."] = "Los documentos de Herod están en una cabaña en el lado oeste de la base; su caja fuerte está más al este, junto a la boca de la cueva.",
		["Panthers, raptors and elder tigers"] = "Panteras, raptores y tigres mayores",
		["River crocolisks"] = "Crocoliscos fluviales",
		["Skullsplitter trolls"] = "Trols Machacacráneos",
		["Snapjaw Crocolisks"] = "Crocoliscos Quijaforte",
		["Stranglethorn Tigers"] = "Tigres de Tuercespina",
		["Take the road north; {npc:738} patrols it, the camp sits in the hills to the west."] = "Toma el camino al norte; {npc:738} lo patrulla, y el campamento está en las colinas al oeste.",
		["The Bloodscalp trolls hold the ruins on the coast west of Nesingwary's camp."] = "Los trols Sangrapellejo ocupan las ruinas de la costa al oeste del campamento de Nesingwary.",
		["The Skullsplitter trolls hold the ruins east of the road between Nesingwary and {object:3202}."] = "Los trols Machacacráneos ocupan las ruinas al este del camino entre Nesingwary y {object:3202}.",
		["The adult tigers prowl the hills just south and west of the camp."] = "Los tigres adultos merodean por las colinas justo al sur y al oeste del campamento.",
		["The haunted island"] = "La isla embrujada",
		["The jungle ruins"] = "Las ruinas de la jungla",
		["The ore drops from Drywhisker kobolds in {zone:1417}"] = "El mineral lo sueltan los kóbolds Mostacho Seco en {zone:1417}",
		["Young tigers and panthers"] = "Tigres jóvenes y panteras",
		["{item:2634}, from a {object:263} crate"] = "{item:2634}, de una caja de {object:263}",
		["{npc:2495}, by the bank"] = "{npc:2495}, junto al banco",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}, en el piso de arriba de la taberna",
		["{npc:2832}, in the {object:56910}"] = "{npc:2832}, en la {object:56910}",
		["{npc:2859}, on the top floor by the docks"] = "{npc:2859}, en el piso superior junto a los muelles",
		["{npc:469}, in the hut"] = "{npc:469}, en la cabaña",
		["{npc:715}, from {zone:1441}"] = "{npc:715}, de {zone:1441}",
		["{npc:716} collects the {item:2755}: the pages drop from almost every humanoid in the jungle. Turn the pages into chapters as you go."] = "{npc:716} colecciona {item:2755}: las páginas las sueltan casi todos los humanoides de la jungla. Convierte las páginas en capítulos sobre la marcha.",
		["{npc:729} and the Lashtail raptors"] = "{npc:729} y los raptores colazote",
		["{npc:737}, in the tavern"] = "{npc:737}, en la taberna",
		["{npc:773}, in the tavern"] = "{npc:773}, en la taberna",
		["{quest:201}: just look around the hunters' camp"] = "{quest:201}: solo echa un vistazo al campamento de los cazadores",
} end)()
t.guides["forever/alliance/30-40/05-arathi-highlands"] = (function() return {
		["Crushridge ogres"] = "Ogros Aplastacresta",
		["Ebenezer Rustlocke"] = "Ebenezer Herrumbra",
		["Escort the professor to the beach north of the cove and guard him while he works; naga attack in waves."] = "Escolta al profesor hasta la playa al norte de la cala y protégelo mientras trabaja; los naga atacan en oleadas.",
		["Fly to {zone:1453}"] = "Vuela a {zone:1453}",
		["For {npc:1440} in {zone:1453}: keep it"] = "Para {npc:1440} en {zone:1453}: guárdalo",
		["Only if Gluggle gave you the pendant in Stranglethorn"] = "Solo si Gluggle te dio el colgante en Tuercespina",
		["Phizzlethorpe"] = "Fiseltor",
		["Shaman training"] = "Entrenamiento de chamán",
		["South-east along the loch to the dig site."] = "Al sureste por la orilla del lago hasta la excavación.",
		["Subdue the succubus"] = "Somete a la súcubo",
		["The two wrecks lie in the bay west of the cove. The charts and logs are inside them; the gems lie on the sea floor around them. Daggerspine naga swim the whole bay."] = "Los dos naufragios están en la bahía al oeste de la cala. Las cartas y los diarios están dentro; las gemas están en el fondo del mar a su alrededor. Los naga Espinadaga nadan por toda la bahía.",
		["The western swamp"] = "El pantano del oeste",
		["The wrecked caravan lies off the road near Biggs."] = "La caravana destrozada está fuera del camino, cerca de Biggs.",
		["The wrecks"] = "Los naufragios",
		["Walk back onto the span: Ebenezer lies under its Arathi end."] = "Vuelve al puente: Ebenezer yace bajo su extremo de Arathi.",
		["West along the coast to the goblins' cove; Lolo keeps watch on the rocks above it."] = "Al oeste por la costa hasta la cala de los goblins; Lolo vigila desde las rocas de encima.",
		["Young crocolisks, Sorrow Spinners and Swamp Jaguars all roam the swamp around the road."] = "Crocoliscos jóvenes, Hilapenas ({npc:858}) y Jaguares del pantano ({npc:767}) recorren el pantano alrededor del camino.",
		["{item:2321} for {npc:2438}'s cloak, from {npc:2381}, if you have none"] = "{item:2321} para la capa de {npc:2438}, de {npc:2381}, si no tienes",
		["{item:3658}: Crushridge ogres"] = "{item:3658}: ogros Aplastacresta",
		["{item:3659}: the {object:1760}"] = "{item:3659}: {object:1760}",
		["{npc:12336}, Cathedral of Light"] = "{npc:12336}, en la catedral",
		["{npc:1440}, the Royal Library in the keep"] = "{npc:1440}, la biblioteca real del castillo",
		["{npc:185335}, at the same circle"] = "{npc:185335}, en el mismo círculo",
		["{npc:217412}: three critters to catch in Arathi, {zone:1443} and Stranglethorn"] = "{npc:217412}: tres alimañas que atrapar en Arathi, {zone:1443} y Tuercespina",
		["{npc:217589}: catch it, for {quest:93176}"] = "{npc:217589}: atrápalo, para {quest:93176}",
		["{npc:2712} and {npc:2713}"] = "{npc:2712} y {npc:2713}",
		["{npc:2713}'s errand"] = "El encargo de {npc:2713}",
		["{npc:2793}, an ogre mage, holds the cave at the southern end of the Witherbark valley."] = "{npc:2793}, un mago ogro, ocupa la cueva del extremo sur del valle Secacorteza.",
		["{npc:5391} is caged at the north end of the sanctuary. Free him and keep him alive on the walk out; his strongbox waits by the road afterwards."] = "{npc:5391} está enjaulado en el extremo norte del santuario. Libéralo y mantenlo con vida durante la salida; después, su caja fuerte espera junto al camino.",
		["{npc:6122} binds the incubus to you"] = "{npc:6122} vincula al íncubo contigo",
		["{npc:6122} waits in the {object:2164}'s cellar, in the {object:2101}. Use the {item:6913} at the summoning circle there and defeat the succubus it calls. If you took {quest:65602}, hand him the {item:190309} too, place it at the same circle and defeat the incubus."] = "{npc:6122} espera en el sótano de {object:2164}, en {object:2101}. Usa el {item:6913} en el círculo de invocación de allí y derrota a la súcubo que aparece. Si aceptaste {quest:65602}, dale también la {item:190309}, colócala en el mismo círculo y derrota al íncubo.",
		["{quest:65602}, if you took it"] = "{quest:65602}, si la aceptaste",
} end)()
t.guides["forever/alliance/30-40/06-badlands"] = (function() return {
		["Fly to Theramore"] = "Vuela a Isla Theramore",
		["Greater Rock Elementals"] = "Elementales de piedra mayores",
		["Lesser Rock Elementals"] = "Elementales de roca inferiores",
		["Maraudine centaurs"] = "Centauros Maraudine",
		["Ogres and buzzards"] = "Ogros y águilas ratoneras",
		["Ride back west to the road and follow it south out of {zone:1432} through the pass into the {zone:1418}. {npc:2910} and {npc:2860} camp side by side at the dig."] = "Cabalga de vuelta al oeste hasta el camino y síguelo hacia el sur, fuera de {zone:1432}, por el paso hasta {zone:1418}. {npc:2910} y {npc:2860} acampan lado a lado en la excavación.",
		["Ride north-east to the abandoned dig; the supply crate lies there among the Dustbelcher ogres."] = "Cabalga hacia el noreste hasta la excavación abandonada; la caja de suministros está ahí, entre los ogros Rotapolvo.",
		["Ride north-east to the dwarven ruins in the north of the {zone:1418}; the chest sits among the Shadowforge dwarves. {npc:2745} nearby is elite: give him room."] = "Cabalga hacia el noreste hasta las ruinas enanas del norte de {zone:1418}; el cofre está entre los enanos Forjatiniebla. {npc:2745}, cerca, es de élite: dale espacio.",
		["Rock Elementals"] = "Elementales de roca",
		["Shadowforge camp"] = "Campamento Forjatiniebla",
		["Take the boat to Theramore from the far pier."] = "Toma el barco a Isla Theramore desde el muelle más lejano.",
		["The Dustbelcher ogres camp just south of the valley; any of them drops scrap. Buzzards circle the plain to the east."] = "Los ogros Rotapolvo acampan justo al sur del valle; cualquiera de ellos suelta chatarra. Las águilas ratoneras sobrevuelan la llanura al este.",
		["The Rock Elementals roam south-east of {npc:2921}; Giant Buzzards and Elder Crag Coyotes share the plain to their west."] = "Los Elementales de roca ({npc:92}) recorren el sureste de {npc:2921}; {npc:2831} y {npc:2729} comparten la llanura al oeste.",
		["The Shadowforge dwarves camp just north of the digsite; the crumpled map lies among their tents. Tunnelers and Darkweavers carry Ryedol's pick. Crag Coyotes roam the slopes around it."] = "Los enanos Forjatiniebla acampan justo al norte de la excavación; el mapa arrugado está entre sus tiendas. Los Tuneladores y los Tejeoscuros llevan el pico de Ryedol. Los Coyotes del risco recorren las laderas de alrededor.",
		["The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south."] = "El esqueleto maltrecho está justo al este de los ogros, en el borde del campamento de troggs Grutacanto; los Cascahuesos y los chamanes de alrededor sueltan las escamas. Theldurin está sentado junto al campamento en ruinas, más al sur.",
		["The clams lie on Stranglethorn's north-west coast, in the next guide: keep it"] = "Las almejas están en la costa noroeste de Vega de Tuercespina, en la siguiente guía: guárdala",
		["The excavation crate"] = "La caja de la excavación",
		["The next guide starts in Theramore."] = "La siguiente guía empieza en Isla Theramore.",
		["The skeleton's next task, Murdaloc, waits until the later {zone:1418} guide at 43."] = "La siguiente tarea del esqueleto, Murdaloc, espera hasta la guía posterior de {zone:1418}, a nivel 43.",
		["The wrecked ship's chest lies on the shore just west of {npc:11863}'s tower."] = "El cofre del barco naufragado está en la orilla, justo al oeste de la torre de {npc:11863}.",
		["The {object:126260}"] = "{object:126260}",
		["Theramore"] = "Isla Theramore",
		["Undead Ravagers roam the bone fields south of the Magram village, east of the Coven; at the far south-east, use the {item:15848} to draw the Magrami Spectres."] = "Los Devastadores no-muertos recorren los campos de huesos al sur de la aldea Magram, al este del Aquelarre; en el extremo sureste, usa {item:15848} para atraer a los Espectros Magrami.",
		["escort {npc:12277} back toward the graveyard"] = "escolta a {npc:12277} de vuelta hacia el cementerio",
		["for the Dustwallow loop in the next guide"] = "para el circuito de Marjal Revolcafango en la siguiente guía",
		["for {npc:2786} in {zone:1455}: keep it"] = "para {npc:2786} en {zone:1455}: guárdala",
		["for {npc:5637} in {zone:1455}: keep it"] = "para {npc:5637} en {zone:1455}: guárdala",
		["only if you carry {item:2868} (a blacksmith's craft)"] = "solo si llevas {item:2868} (una creación de herrero)",
		["{npc:12277} is held in the centaur camp west of the graveyard. Free her and keep her alive on the walk out; she stops by the graveyard."] = "{npc:12277} está retenida en el campamento centauro al oeste del cementerio. Libérala y mantenla con vida durante la salida; se detiene junto al cementerio.",
		["{npc:12369}, a centaur chieftain, camps on the north-west coast, north of {npc:11863}'s tower."] = "{npc:12369}, un jefe centauro, acampa en la costa noroeste, al norte de la torre de {npc:11863}.",
		["{npc:1470}, in the inn"] = "{npc:1470}, en la posada",
		["{npc:217590}: catch it, for My Little Friends"] = "{npc:217590}: atrápalo, para My Little Friends",
		["{npc:2920}, beside {npc:2921}"] = "{npc:2920}, junto a {npc:2921}",
		["{npc:2921}'s next test needs crafted gear: skip it."] = "La siguiente prueba de {npc:2921} requiere equipo fabricado: omítela.",
		["{npc:5638}'s next task, {item:6245}, is a drop on the far coast: skip it."] = "La siguiente tarea de {npc:5638}, {item:6245}, se obtiene en la costa lejana: omítela.",
} end)()
t.guides["forever/alliance/40-50/01-stranglethorn-vale"] = (function() return {
		["\"Stinky\" Ignatz"] = "\"Apestoso\" Ignatz",
		["Bloodsail camp"] = "Campamento Velasangre",
		["Bloodsail pirates"] = "Piratas Velasangre",
		["Cold Eye Basilisks"] = "Basiliscos Ojogélido",
		["Defeat the challengers and {npc:6238}"] = "Derrota a los retadores y a {npc:6238}",
		["Every Zanzil follower can drop the mixture; {npc:2537} walks the south of the camp."] = "Cualquier seguidor de Zanzil puede soltar la mezcla; {npc:2537} recorre el sur del campamento.",
