		["{npc:7955}: other colours, 20g"] = "{npc:7955}: otros colores, 20g",
		["{object:56910} is the tall building over the harbour; most of the quest givers are on its floors or the docks below."] = "{object:56910} es el edificio alto sobre el puerto; la mayoría de los asignadores de misiones están en sus pisos o en los muelles de abajo.",
		["{quest:1260} stands near the inn; {npc:4897}, a trade supplier a few steps south, sells the spices Jarl wants."] = "{quest:1260} está cerca de la posada; {npc:4897}, una proveedora de comercio a pocos pasos al sur, vende las especias que quiere Jarl.",
		["{zone:1453} has no shaman trainer"] = "{zone:1453} no tiene instructor de chamanes",
} end)()
t.guides["forever/alliance/40-50/02-badlands"] = (function() return {
		["Blue Pearls from Stranglethorn"] = "Perlas azules de Vega de Tuercespina",
		["On to Feathermoon"] = "Rumbo a Bastión Plumaluna",
		["Ride south out of {zone:1432} through the pass into the {zone:1418}; {npc:2860} camps at the dig."] = "Cabalga hacia el sur, fuera de {zone:1432}, por el paso hasta {zone:1418}; {npc:2860} acampa en la excavación.",
		["Take the boat to Theramore from the far pier."] = "Toma el barco a Isla Theramore desde el muelle más lejano.",
		["Talonaxe's next task waits for a later {zone:1425} guide."] = "La siguiente tarea de Talonaxe espera a una guía posterior de {zone:1425}.",
		["The Scalding Whelps nest in the ravine east of {npc:2888}; leave the Scorched Guardians (elite) alone. The {item:4612} drops rarely: take it if it comes while you grind."] = "Las Crías hirvientes anidan en el barranco al este de {npc:2888}; deja en paz a los Guardianes abrasados (élite). {item:4612} cae rara vez: tómalo si aparece mientras cazas.",
		["The battered skeleton lies at the edge of the Stonevault trogg camp; {quest:739}, Agmond's killer, walks among the Bonesnappers."] = "El esqueleto maltrecho está en el borde del campamento de troggs Grutacanto; {quest:739}, el asesino de Agmond, camina entre los Cascahuesos.",
		["The first two cages stand together in the Witherbark village south of {npc:5634}; the third is in the next village to the east. Every Witherbark troll can drop a necklace."] = "Las dos primeras jaulas están juntas en la aldea Secacorteza al sur de {npc:5634}; la tercera está en la siguiente aldea al este. Cualquier trol Secacorteza puede soltar un collar.",
		["Theramore"] = "Isla Theramore",
		["Warlock: {quest:3631}"] = "Brujo: {quest:3631}",
		["Witherbark villages"] = "Aldeas Secacorteza",
		["{npc:1573}, the {object:32372}"] = "{npc:1573}, {object:32372}",
		["{npc:2616} stands on the docks where the boat lands."] = "{npc:2616} está en los muelles donde llega el barco.",
		["{npc:2817}'s next quest pays no experience: skip it."] = "La siguiente misión de {npc:2817} no da experiencia: omítela.",
		["{npc:2888}'s next task is an elite hunt: skip it."] = "La siguiente tarea de {npc:2888} es una cacería de élite: omítela.",
		["{npc:5634}'s cocktail needs parts from Kalimdor: skip it."] = "El cóctel de {npc:5634} requiere piezas de Kalimdor: omítelo.",
		["{npc:5636}, beside the flight master at the top"] = "{npc:5636}, junto al maestro de vuelo en la cima",
		["{npc:7884} keeps paying for necklaces: hand in any extras"] = "{npc:7884} sigue pagando por collares: entrega los que te sobren",
} end)()
t.guides["forever/alliance/40-50/03-feralas"] = (function() return {
		["Giants and elementals"] = "Gigantes y elementales",
		["Gordunni ogres"] = "Ogros Gordunni",
		["Grimtotem camp"] = "Campamento Tótem Siniestro",
		["Grimtotem tauren"] = "Taurens Tótem Siniestro",
		["Grind to 45"] = "Sube a nivel 45 matando",
		["Hatecrest naga"] = "Nagas Crestafuria",
		["Hearth to Feathermoon."] = "Usa la Piedra de hogar para volver a Plumaluna.",
		["Rage Scar yetis"] = "Yetis Cicatriz de Rabia",
		["Ride back west along the road, then north into the Rage Scar hills. Every yeti here can drop a hide; one may drop a {quest:7735}, which {npc:7852} pays for too."] = "Cabalga de vuelta al oeste por el camino y luego al norte hacia las colinas Cicatriz de Rabia. Cualquier yeti de aquí puede soltar una piel; alguno puede soltar una {quest:7735}, que {npc:7852} McGrubben también paga.",
		["Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north."] = "Cabalga al este hasta el campamento Gordunni en las colinas al sureste del valle de los yetis: brujos y chamanes ocupan el campamento, y toscos rondan las laderas a su alrededor y más al norte.",
		["Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; {npc:5346} (level 48) prowls the middle."] = "Cabalga al norte hacia el valle de los yetis. Cualquier yeti Cicatriz Feral puede soltar una piel gruesa; {npc:5346} (nivel 48) merodea por el centro.",
		["Ride north-east to the night elf outpost on the {zone:1441} border."] = "Cabalga al noreste hasta el puesto de los elfos de la noche en la frontera de {zone:1441}.",
		["Ride west to the friendly mountain giant at the foot of the hills. Land Walkers and Cliff Giants around him are elite: give them room."] = "Cabalga al oeste hasta el gigante de montaña amistoso al pie de las colinas. Los caminatierras y gigantes del risco a su alrededor son élite: mantén la distancia.",
		["Ring the bell whenever {npc:7774} stops to wander, and lead her south to {npc:7765}."] = "Toca la campana cada vez que {npc:7774} se detenga a deambular y llévala al sur hasta {npc:7765}.",
		["Shore Striders, Deep Striders and Wave Striders (elite giants) wade along the coast north of the dock: zap one with {item:18904} and kill the shrunken giant. Sea Elementals and Sea Sprays drift in the same surf."] = "Los zancaorillas, zancaprofundas y asaltaolas (gigantes élite) vadean la costa al norte del muelle: dispárale a uno con {item:18904} y mata al gigante encogido. Los elementales de mar y rocíos del mar flotan en el mismo oleaje.",
		["The courier's boat"] = "El bote del mensajero",
		["Walk south along the island to the naga ruins; the gazebo stands among them."] = "Camina al sur por la isla hasta las ruinas naga; el cenador está entre ellas.",
		["for Tyrande in {zone:1457}: the route takes you there at 47"] = "para Tyrande Susurravientos en {zone:1457}: la ruta te lleva allí a nivel 47",
		["if you carry {quest:1100} from {zone:1441}"] = "si llevas {quest:1100} de {zone:1441}",
		["{item:11463}, from the backpacks"] = "{item:11463}, de las mochilas",
		["{npc:14637}'s refills are level 55: skip them."] = "Las recargas de {npc:14637} son de nivel 55: omítelas.",
		["{npc:3936}, beside him"] = "{npc:3936}, a su lado",
		["{npc:7774} wanders the hills north of {npc:7765}, among the Northspring harpies; her bell is in the chest beside her."] = "{npc:7774} deambula por las colinas al norte de {npc:7765}, entre las arpías Nortearroyo; su campana está en el cofre a su lado.",
		["{npc:7774}'s escort"] = "La escolta de {npc:7774}",
		["{npc:7877}, at the top of the stronghold"] = "{npc:7877}, en lo alto del bastión",
		["{npc:8136} waits for the end of the mainland loop."] = "{npc:8136} espera hasta el final de la vuelta por el continente.",
} end)()
t.guides["forever/alliance/40-50/04-tanaris"] = (function() return {
		["Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. {npc:7883} stands on the far side; {npc:7881}'s stolen cargo lies in the camp."] = "Sigue la costa al sur hasta la cala pirata. Los piratas de los Mares del Sur llenan la playa y los barcos: avanza por el borde y atráelos de uno en uno. {npc:7883} está en el otro extremo; la carga robada de {npc:7881} está en el campamento.",
		["Gives the {item:8585}"] = "Da el {item:8585}",
		["He runs off to keep Rizzle busy"] = "Se va corriendo para entretener a Rizzle Pernolatón",
		["Ride east across the dunes to the goblin harbour on the north-east coast."] = "Cabalga al este por las dunas hasta el puerto goblin de la costa noreste.",
		["Ride north-west to the Centipaar hive in the dunes. Any Centipaar can drop insect parts."] = "Cabalga al noroeste hasta la colmena Centipaar en las dunas. Cualquier Centipaar puede soltar partes de insecto.",
		["Ride south into {quest:3362}. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley. The Thistleshrubs are 48-50, above you: pull one at a time."] = "Cabalga al sur hacia {quest:3362}. Los colectores de rocío Cardizal sueltan las glándulas; solo algunas están llenas, así que guarda la cargada. Los cardizales nudosos y enraizadores Cardizal comparten el valle. Los Cardizal son de nivel 48-50, por encima del tuyo: atráelos de uno en uno.",
		["Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; {npc:12046} (49) stands in the middle with guards around him: clear them first."] = "Cabalga al suroeste hasta la base ogra. La llenan toscos y déspotas (46-48); {npc:12046} (49) está en el centro rodeado de guardias: elimínalos primero.",
		["Rizzle's plans"] = "Los planos de Rizzle Pernolatón",
		["The Wanted poster beside him"] = "El cartel de Se busca a su lado",
		["Wastewander bandits"] = "Bandidos Vagayermo",
		["While {npc:4709} keeps Rizzle talking, his plans lie unguarded in the gnome camp across the track."] = "Mientras {npc:4709} distrae a Rizzle Pernolatón, sus planos quedan sin vigilancia en el campamento gnomo al otro lado de la pista.",
		["for {zone:1457}: the route takes you there at 47"] = "para {zone:1457}: la ruta te lleva allí a nivel 47",
		["{npc:11758}, on the east side of town"] = "{npc:11758}, en el lado este del pueblo",
		["{npc:5955}'s escort"] = "La escolta de {npc:5955}",
		["{npc:7407}, by the water tower"] = "{npc:7407}, junto a la torre de agua",
		["{npc:7408}, next to him"] = "{npc:7408}, a su lado",
		["{npc:7583}'s next ingredient grows in the {zone:1425}, and the route never brings it back: skip it."] = "El siguiente ingrediente de {npc:7583} crece en {zone:1425} y la ruta nunca te trae de vuelta: omítelo.",
		["{npc:7881}, in the port's tavern"] = "{npc:7881}, en la taberna del puerto",
		["{quest:2864}, north side of town"] = "{quest:2864}, en el lado norte del pueblo",
} end)()
t.guides["forever/alliance/40-50/05-the-hinterlands"] = (function() return {
		["Ashmane Boars and Redstone Basilisks share the slopes south-west of the keep. Keep clear of the Helboars further south: they are level 52."] = "Los jabalíes Cenicrín y basiliscos Rocarroja comparten las laderas al suroeste del castillo. Aléjate de los jabinfernos más al sur: son de nivel 52.",
		["Boars and basilisks"] = "Jabalíes y basiliscos",
		["Hearthstone on cooldown? Ride back north-west."] = "¿Piedra de hogar en tiempo de reutilización? Cabalga de vuelta al noroeste.",
		["Ride back north to Ironband's camp."] = "Cabalga de vuelta al norte hasta la Excavación de Vetaferro.",
		["Ride east along the south shore of the loch to Ironband's camp."] = "Cabalga al este por la orilla sur del lago hasta la Excavación de Vetaferro.",
		["Ride east through {zone:1430} into the {zone:1435} and south down the road into the {zone:1419}. The bloodmages' camp is the first stop beside the road."] = "Cabalga al este por {zone:1430} hasta {zone:1435} y baja al sur por el camino hasta {zone:1419}. El campamento de los magos de sangre es la primera parada junto al camino.",
		["Ride west: Starving Snickerfangs roam the dry hills just south of the bloodmages' camp; Scorpok Stingers (level 50) scuttle across the middle of the north. {npc:5982} vultures circle over all of it. Pull one at a time."] = "Cabalga al oeste: las hienas risitas famélicas rondan las colinas secas justo al sur del campamento de los magos de sangre; los aguijoneros Scorpok (nivel 50) corretean por el centro del norte. Los buitres {npc:5982} vuelan en círculos por toda la zona. Atráelos de uno en uno.",
		["Scorpoks and snickerfangs"] = "Scorpoks e hienas risitas",
		["Step through the portal into {zone:1457}. The Temple of the Moon is in the south of the city."] = "Cruza el portal hacia {zone:1457}. El Templo de la Luna está en el sur de la ciudad.",
		["Temple of the Moon"] = "Templo de la Luna",
		["The bloodmages"] = "Los magos de sangre",
		["The bloodmages' second tier pays for the same parts with a buff item and no experience: skip it."] = "El segundo nivel de los magos de sangre paga las mismas partes con un objeto de beneficio y sin experiencia: omítelo.",
		["The druid trainers stand in the Enclave; {zone:1455} has none"] = "Los instructores de druida están en el Enclave Cenarion; {zone:1455} no tiene",
		["the book on her table"] = "el libro de su mesa",
		["the soil comes from {zone:1449}, later"] = "la tierra viene de {zone:1449}, más adelante",
		["{npc:3516}, at the top of the tree"] = "{npc:3516}, en lo alto del árbol",
		["{npc:7740}, beside her"] = "{npc:7740}, a su lado",
		["{npc:7744}: the last guide binds here, so this usually ticks at once"] = "{npc:7744}: la guía anterior te vincula aquí, así que esto suele marcarse de inmediato",
		["{npc:7907}'s next errand goes to {zone:1446}: skip it."] = "El siguiente encargo de {npc:7907} va a {zone:1446}: omítelo.",
		["{npc:7916}: keep it, the feathers come at the end of the {zone:1428} guide"] = "{npc:7916}: guárdala, las plumas llegan al final de la guía de {zone:1428}",
		["{quest:2990}, at the top of the keep"] = "{quest:2990}, en lo alto del castillo",
} end)()
t.guides["forever/alliance/40-50/06-searing-gorge"] = (function() return {
		["For {npc:8256} in {zone:1455}, later"] = "Para {npc:8256} en {zone:1455}, más adelante",
		["Golems and elementals"] = "Gólems y elementales",
		["Greater Lava Spiders"] = "Arañas de lava superiores",
		["Heavy War Golems patrol the floor of the Cauldron below Kalaran; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts."] = "Los gólems de guerra pesados patrullan el fondo de La Caldera, debajo de Kalaran Espada del Viento; los elementales de magma flotan entre ellos. Los gólems y elementales sueltan el aceite; los elementales, los corazones.",
		["Taskmasters and Slavers drive the slaves all over the Cauldron, and any of them can carry a {item:10551}. The Steamsmiths work at the furnaces in the middle (the {item:18959}), the Lookouts stand on the southern ridges (the Spyglass). Any {object:147516} may drop the {item:11818}: keep it."] = "Los capataces y esclavistas Hierro Negro arrean a los esclavos por toda La Caldera, y cualquiera puede llevar una {item:10551}. Los vapoherreros trabajan en las forjas del centro (la {item:18959}) y los oteadores están en las crestas del sur (el Catalejo de oteador). Cualquier enano {object:147516} puede soltar la {item:11818}: guárdala.",
		["The Grimesilt outhouse"] = "La letrina de Limugre",
		["The prisoner's next task, Ledger from {zone:1446}, sends you to the {zone:1435} and {zone:1445}: skip it."] = "La siguiente tarea del prisionero, El libro de contabilidad de {zone:1446}, te envía a {zone:1435} y {zone:1445}: omítela.",
		["The spiders roam the plateaus and lava pools in the south-west of the gorge."] = "Las arañas rondan las mesetas y los charcos de lava del suroeste de la garganta.",
		["The {object:179827} board"] = "El tablón {object:179827}",
		["{npc:6734}: the last guide hearths you here, so this usually ticks at once"] = "{npc:6734}: la guía anterior te trae aquí con la piedra de hogar, así que esto suele marcarse de inmediato",
		["{object:147516} dwarves"] = "Enanos {object:147516}",
} end)()
t.guides["forever/alliance/40-50/07-un-goro-crater"] = (function() return {
		["Archesonus stands beside King Magni in the {object:171709}."] = "Archesonus está junto al rey Magni en {object:171709}.",
		["Bind and train"] = "Vincúlate y entrena",
		["Bones and equipment"] = "Huesos y equipo",
		["Cross the south of the crater to {npc:9619} by the ramp."] = "Cruza el sur del cráter hasta {npc:9619}, junto a la rampa.",
		["Dinosaur Bones lie on the ground in the south-west, among the stegodons: those are elite, pick the bones up around them and take the rest from Diemetradons. The expedition's {item:11112} lies in the south-west jungle."] = "Los huesos de dinosaurio están en el suelo del suroeste, entre los estegodones: son élite, recoge los huesos a su alrededor y consigue el resto de los diemetradones. {item:11112} de la expedición está en la jungla del suroeste.",
		["Eastern Pylon"] = "Pilón este",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "Termina con {npc:9298} en {zone:1452}: guárdala",
		["Escort {npc:9999}"] = "Escolta a {npc:9999}",
		["For {npc:7775} in {zone:1444}: keep it"] = "Para {npc:7775} en {zone:1444}: guárdala",
		["Four rune rubbings in {zone:1447}: keep it"] = "Cuatro calcos de runas en {zone:1447}: guárdala",
		["Grind to 50"] = "Farmea hasta el 50",
		["Grind to 51"] = "Farmea hasta el 51",
		["Lar'korwi Mates and the raft"] = "Compañeras de Lar'korwi ({npc:9683}) y la balsa",
		["Northern Pylon"] = "Pilón norte",
		["Ride down the ramp into the crater: {npc:9619} camps at its foot."] = "Baja por la rampa al cráter: {npc:9619} acampa al pie.",
		["Ride north along the east side to the gorilla plateau. {npc:9622}, a level 55 gorilla, sits in its deepest cave: clear the gorillas at the cave mouth first."] = "Cabalga al norte por el lado este hasta la meseta de los gorilas. {npc:9622}, un gorila de nivel 55, está en su cueva más profunda: limpia antes los gorilas de la boca de la cueva.",
		["Ride north along the western jungle back to the refuge."] = "Cabalga al norte por la jungla del oeste de vuelta al refugio.",
		["Ride south along the eastern cliffs to {npc:9619} at the foot of the ramp."] = "Cabalga al sur por los acantilados del este hasta {npc:9619}, al pie de la rampa.",
		["Ride south down the east side. Young Diemetradons graze the eastern jungle and {npc:9165} fly near the eastern cliffs; both drop {npc:9998}'s scales."] = "Cabalga al sur por el lado este. Los diemetradones jóvenes pastan en la jungla del este y los {npc:9165} vuelan cerca de los acantilados del este; ambos sueltan las escamas para {npc:9998}.",
		["Ride west back to the refuge."] = "Cabalga al oeste de vuelta al refugio.",
		["Ride west from {npc:9619}: the silithid hive fills the south of the crater. Use the Scraping Vial on a hatchery, a chamber with hanging larvae. Gorishi wasps and workers drop {quest:3764}; {npc:9166} nest on the southern cliffs if you still need kills."] = "Cabalga al oeste desde {npc:9619}: la colmena silítida ocupa el sur del cráter. Usa el vial de raspadura en un criadero, una cámara con larvas colgantes. Las avispas y trabajadores Gorishi sueltan {quest:3764}; los {npc:9166} anidan en los acantilados del sur si aún te faltan muertes.",
		["The Gorishi hive"] = "La colmena Gorishi",
		["The Lar'korwi Mates prowl the jungle west of {npc:9619}. The wrecked raft lies on the shore of the lake there; the small pack sits in the water beside it. Keep the compass, map and key for {npc:8737}. Any beast in the crater may drop {item:11116}: right-click it."] = "Las Compañeras de Lar'korwi ({npc:9683}) merodean por la jungla al oeste de {npc:9619}. La balsa destrozada está en la orilla del lago de allí; la mochila pequeña está en el agua a su lado. Guarda la brújula, el mapa y la llave para {npc:8737}. Cualquier bestia del cráter puede soltar {item:11116}: haz clic derecho en él.",
		["The dead Threshadon lies by the water north of {npc:9619}."] = "El trillanodonte muerto está junto al agua, al norte de {npc:9619}.",
		["The east side"] = "El lado este",
		["The pelts come after loop 2, on the gorilla plateau"] = "Las pieles vienen después del circuito 2, en la meseta de los gorilas",
		["The pylon stands on the eastern cliffs."] = "El pilón está en los acantilados del este.",
		["The pylon stands on the slope east of the refuge. {npc:9166} circle the slopes around it: they count for {npc:9997} and drop {npc:9998}'s scales."] = "El pilón está en la ladera al este del refugio. Los {npc:9166} vuelan en círculos por las laderas a su alrededor: cuentan para {npc:9997} y sueltan las escamas para {npc:9998}.",
		["The pylon stands on the western cliffs. {npc:9167} fly over the whole west side."] = "El pilón está en los acantilados del oeste. Los {npc:9167} vuelan sobre todo el lado oeste.",
		["The relics are in the {zone:1428}: keep it"] = "Las reliquias están en {zone:1428}: guárdala",
		["The wooden sign beside {npc:9997}"] = "El letrero de madera junto a {npc:9997}",
		["Western Pylon"] = "Pilón oeste",
		["Xiggs waits in the {object:32359}."] = "Xiggs espera en {object:32359}.",
		["{npc:11406}: for Ogtinc in {zone:1447}, keep it"] = "{npc:11406}: para Ogtinc en {zone:1447}, guárdala",
		["{npc:6734}: the last guide hearths you here, so this usually ticks at once"] = "{npc:6734}: la guía anterior te trae aquí con la piedra de hogar, así que esto suele marcarse de inmediato",
		["{npc:9117}, at the back of the cave"] = "{npc:9117}, al fondo de la cueva",
		["{npc:9616}: the oozes are in {zone:1448}, keep it"] = "{npc:9616}: los mocos están en {zone:1448}, guárdala",
		["{npc:9618} stands just outside the refuge."] = "{npc:9618} está justo afuera del refugio.",
		["{npc:9684}'s lair lies in the jungle north of {npc:9619}, below the eastern cliffs: use {item:11568} there. {npc:9684} is level 56: start at full health."] = "La guarida de {npc:9684} está en la jungla al norte de {npc:9619}, bajo los acantilados del este: usa {item:11568} allí. {npc:9684} es de nivel 56: empieza con la salud completa.",
		["{npc:9997}'s friend {npc:9999} has gone missing."] = "{npc:9999}, el amigo de {npc:9997}, ha desaparecido.",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}, en la entrada del refugio",
		["{npc:9998}, at the refuge's entrance"] = "{npc:9998}, en la entrada del refugio",
} end)()
t.guides["forever/alliance/50-60/01-burning-steppes"] = (function() return {
		["Druid training"] = "Entrenamiento de druida",
