		["Kolkar Wranglers and Stormers hold the camps south of {npc:3389}."] = "Los retadores y agitadoras Kolkar ocupan los campamentos al sur de {npc:3389}.",
		["Kolkar camps"] = "Campamentos Kolkar",
		["Plainstriders and raptors"] = "Zancudos y raptores",
		["Raptor nests"] = "Nidos de raptor",
		["Razormane camp"] = "Campamento Crines de Acero",
		["South to {npc:3389}'s watch post on the Kolkar border."] = "Al sur, al puesto de vigilancia de {npc:3389} en la frontera Kolkar.",
		["Southsea beach"] = "Playa de los Mares del Sur",
		["The Savannah Prowlers hunt the plains between town and the Razormane camp to the east. In the camp, Water Seekers and Thornweavers hold the western half, Hunters the middle; the supply crates sit at its eastern end."] = "Los merodeadores de la sabana cazan en las llanuras entre el pueblo y el campamento Crines de Acero, al este. En el campamento, los buscaquas y tejespinas ocupan la mitad oeste, y los cazadores, el centro; las cajas de suministros están en su extremo este.",
		["The pools lie just north of {npc:3389}. Walk into the water to explore them; the Laden Mushrooms for Helbrim grow around them. Kill every Kolkar you pass for bracers."] = "Las Charcas del Olvido están justo al norte de {npc:3389}. Métete en el agua para explorarlas; los champiñones cargados para Helbrim crecen a su alrededor. Mata a todos los Kolkar que encuentres para conseguir brazales.",
		["Thunder lizards across the river"] = "Truenagartos al otro lado del río",
		["Zhevra"] = "Zhebras",
		["Zhevra Runners graze north and east of town."] = "Los galopadores zhebra pastan al norte y al este del pueblo.",
		["{npc:3615}, the wind rider master"] = "{npc:3615}, el maestro de jinetes del viento",
		["{npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "{npc:5900} hace {item:6636} con el alquitrán y la bolsa. Úsalo junto al brasero a su lado para revelar a {npc:5893}, mátala para obtener {item:6655} y luego coloca la brasa en el brasero.",
		["{npc:5907} stands on the ridge north of the Razormane camp."] = "{npc:5907} está en la loma al norte del campamento Crines de Acero.",
		["{npc:5907}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:5907}: {npc:2523}, tu {item:5176} y {item:263412}",
