t.guides["forever/legacy/legacy-challenges"] = (function() return {
		["Adventure: explore the world map"] = "Aventura: explora el mapa del mundo",
		["Adventure: {npc:16042}"] = "Aventura: {npc:16042}",
		["Adventure: {quest:8997} (Alliance)"] = "Aventura: {quest:8997} (Alianza)",
		["Adventure: {quest:8998} (Horde)"] = "Aventura: {quest:8998} (Horda)",
		["All 13 Hyjal Summit bosses are a point. Hyjal Summit is a new Forever raid; its bosses are not in our data, so tick it off once all 13 are down."] = "Los 13 jefes de Hyjal Summit valen un punto. Hyjal Summit es una nueva banda de Forever; sus jefes no están en nuestros datos, así que márcala cuando caigan los 13.",
		["All 8 Barrow Deeps bosses are a point. Barrow Deeps is a new Forever raid; its bosses are not in our data, so tick it off once all 8 are down."] = "Los 8 jefes de Barrow Deeps valen un punto. Barrow Deeps es una nueva banda de Forever; sus jefes no están en nuestros datos, así que márcala cuando caigan los 8.",
		["Blizzard counts four battleground reputations, but our faction data has three per side ({zone:1460}, {zone:1461}, {zone:1459}). The fourth is likely tied to Forever's new PvP content; check the in-game Legacy panel."] = "Blizzard cuenta cuatro reputaciones de campos de batalla, pero nuestros datos de facciones tienen tres por bando ({zone:1460}, {zone:1461}, {zone:1459}). La cuarta probablemente está ligada al nuevo contenido JcJ de Forever; revisa el panel de Legado en el juego.",
		["Classes give 27 points: every class reaching 25, 45 and 60. They count once per class across your account, so a second character of a class you already raised adds nothing; a new class does. The first character to reach 25 usually unlocks the Legacy System itself."] = "Las clases dan 27 puntos: cada clase que llega a 25, 45 y 60. Cuentan una vez por clase en toda tu cuenta, así que un segundo personaje de una clase que ya subiste no suma nada; una clase nueva sí. El primer personaje que llega a 25 suele desbloquear el propio Sistema de Legado.",
		["Classes: level 25"] = "Clases: nivel 25",
		["Classes: level 45"] = "Clases: nivel 45",
		["Classes: level 60"] = "Clases: nivel 60",
		["Dire Maul East"] = "La Masacre: Este",
		["Dire Maul North"] = "La Masacre: Norte",
		["Dire Maul West"] = "La Masacre: Oeste",
		["Dungeons: level 15-25"] = "Calabozos: nivel 15-25",
		["Dungeons: level 26-45"] = "Calabozos: nivel 26-45",
		["Dungeons: level 46-60"] = "Calabozos: nivel 46-60",
		["Each crafting profession gives 3 points, at 150, 225 and 300. Ranks count once per profession across your account. Follow the Polestar guide \"{skill:171} 1-300\" (Professions). A crafting profession at 150 also unlocks the Legacy System."] = "Cada profesión de fabricación da 3 puntos, a 150, 225 y 300. Los rangos cuentan una vez por profesión en toda tu cuenta. Sigue la guía de Polestar \"{skill:171} 1-300\" (Profesiones). Una profesión de fabricación en 150 también desbloquea el Sistema de Legado.",
		["Exalted with each battleground faction is worth a point (4 in all; this page shows three, see the note). Follow the Polestar Reputation guides Warsong Gulch Reputation, Arathi Basin Reputation and Alterac Valley Reputation. The Diplomat Legacy perk increases reputation gains."] = "Ser Exaltado con cada facción de campo de batalla vale un punto (4 en total; esta página muestra tres, ver la nota). Sigue las guías de Reputación de Polestar: Reputación: Garganta Grito de Guerra, Reputación: Cuenca de Arathi y Reputación: Valle de Alterac. La ventaja Diplomático del Legado aumenta la reputación obtenida.",
		["Exploring the entire world map on one character is a point, and it can also unlock the Legacy System. It must all be on the same character."] = "Explorar todo el mapa del mundo con un personaje vale un punto y también puede desbloquear el Sistema de Legado. Todo debe hacerse con el mismo personaje.",
		["Follow the Polestar Exploration guides: Exploration: Eastern Kingdoms 1-30, 30-45 and 45-60, and Exploration: Kalimdor 1-30, 30-45 and 45-60. They track every area as you discover it."] = "Sigue las guías de Exploración de Polestar: Exploración: Reinos del Este 1-30, 30-45 y 45-60, y Exploración: Kalimdor 1-30, 30-45 y 45-60. Registran cada área a medida que la descubres.",
		["Follow the Polestar guide \"{skill:164} 1-300\" (Professions)."] = "Sigue la guía de Polestar \"{skill:164} 1-300\" (Profesiones).",
		["Follow the Polestar guide \"{skill:165} 1-300\" (Professions)."] = "Sigue la guía de Polestar \"{skill:165} 1-300\" (Profesiones).",
		["Follow the Polestar guide \"{skill:197} 1-300\" (Professions)."] = "Sigue la guía de Polestar \"{skill:197} 1-300\" (Profesiones).",
		["Follow the Polestar guide \"{skill:202} 1-300\" (Professions)."] = "Sigue la guía de Polestar \"{skill:202} 1-300\" (Profesiones).",
		["Follow the Polestar guide \"{skill:333} 1-300\" (Professions)."] = "Sigue la guía de Polestar \"{skill:333} 1-300\" (Profesiones).",
		["Forever's new dungeons"] = "Los nuevos calabozos de Forever",
